document.querySelectorAll('[data-countdown]').forEach(node=>{const target=new Date(node.dataset.countdown);function tick(){const ms=Math.max(0,target-Date.now()),d=Math.floor(ms/864e5),h=Math.floor(ms/36e5)%24,m=Math.floor(ms/6e4)%60,s=Math.floor(ms/1000)%60;node.textContent=ms?`${d}d ${String(h).padStart(2,'0')}h ${String(m).padStart(2,'0')}m ${String(s).padStart(2,'0')}s`:'Announcement time reached · verify official result';}tick();setInterval(tick,1000)});
const pageKey=document.body.dataset.reviewKey;
if(pageKey){const buttons=[...document.querySelectorAll('.review-toggle')],bar=document.querySelector('.progress-box i'),label=document.querySelector('.progress-text');function draw(){const tc=document.documentElement.lang==='zh-Hant';let n=0;buttons.forEach((b,i)=>{const done=localStorage.getItem(`${pageKey}-${i}`)==='1';b.classList.toggle('done',done);b.textContent=done?(tc?'✓ 已複習':'✓ Reviewed'):(tc?'標記已複習':'Mark reviewed');if(done)n++});bar.style.width=`${n/3*100}%`;label.textContent=tc?`${n} / 3 已複習`:`${n} / 3 reviewed`;};buttons.forEach((b,i)=>b.addEventListener('click',()=>{const k=`${pageKey}-${i}`;localStorage.setItem(k,localStorage.getItem(k)==='1'?'0':'1');draw()}));window.addEventListener('nobel:languagechange',draw);draw();}
(()=>{const source=document.currentScript?.src;if(!source||window.__nobelGlobalNavRequested)return;window.__nobelGlobalNavRequested=true;const script=document.createElement('script');script.src=new URL('global-nav.js',source);document.head.append(script);})();
